require_once __DIR__.'/core.php';require_once __DIR__.'/federation_lib.php';require_once __DIR__.'/maintenance.php';tt_require_login();$db=tt_db_open(true);$uid=(int)$_SESSION['id'];$q=tt_prepare($db,'SELECT `hostmode` FROM `accounts` WHERE `id`=?');$q->bind_param('i',$uid);$q->execute();$q->bind_result($hostmode);$q->fetch();$q->close();if((int)$hostmode<1){$db->close();tt_fail('Host-node operator access required.',403,'Federation');}$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{if(isset($_POST['add'])){$url=tt_validate_peer_url((string)($_POST['url']??''));if(!$url)throw new RuntimeException('Use a public HTTPS Tabletime node URL.');$tier=in_array($_POST['tier']??'host',['host','admin'],true)?$_POST['tier']:'host';tt_preflight_write($db,4096,true);$s=tt_prepare($db,'INSERT INTO `federation_peers` (`base_url`,`tier`,`enabled`,`created_at`) VALUES(?,?,1,UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE `tier`=VALUES(`tier`),`enabled`=1');$s->bind_param('ss',$url,$tier);if(!$s->execute())throw new RuntimeException($s->error);$s->close();$msg='Peer added.';}if(isset($_POST['disable'])){$id=(int)$_POST['disable'];$s=tt_prepare($db,'UPDATE `federation_peers` SET `enabled`=0 WHERE `id`=?');$s->bind_param('i',$id);$s->execute();$s->close();$msg='Peer disabled.';}if(isset($_POST['sync'])){$id=(int)$_POST['sync'];$r=tt_sync_peer($db,$id);$msg=$r['ok']?'Sync complete; imported '.(int)($r['imported']??0).' posts.':'Sync failed: '.($r['message']??'unknown');}}catch(Throwable $e){$err=$e->getMessage();}}
$peers=[];$r=$db->query('SELECT `id`,`base_url`,`tier`,`enabled`,`cursor_at`,`last_sync_at`,`last_error` FROM `federation_peers` ORDER BY `enabled` DESC,`id` DESC');if($r){$peers=$r->fetch_all(MYSQLI_ASSOC);$r->free();}$db->close();
?><!doctype html><html class="tabletime"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.php"><title>Tabletime · Federation</title></head><body><?php tt_nav('extend.php');?><main class="content"><h2>Federation / uplink</h2><p>This node pulls only <b>public/global</b> posts from operator-approved peers. Private posts and credentials never federate.</p><?php if($msg):?><p class="notice ok"><?=tt_h($msg)?></p><?php endif;?><?php if($err):?><p class="notice error"><?=tt_h($err)?></p><?php endif;?><section class="card"><h3>Add peer</h3><form method="post"><input name="url" type="url" placeholder="https://other-node.example/tabletime" required><select name="tier"><option value="host">Host node</option><option value="admin">Admin/coordinator</option></select><button name="add" value="1">Add uplink</button></form></section><section class="grid"><?php foreach($peers as $p):?><article class="card"><h3><?=tt_h($p['base_url'])?></h3><p><?=tt_h($p['tier'])?> · <?=$p['enabled']?'enabled':'disabled'?></p><p class="meta">Cursor <?=tt_h($p['cursor_at'])?> · last sync <?=tt_h($p['last_sync_at'])?></p><?php if($p['last_error']):?><p><?=tt_h($p['last_error'])?></p><?php endif;?><form method="post"><button name="sync" value="<?=(int)$p['id']?>">Sync now</button><?php if($p['enabled']):?><button name="disable" value="<?=(int)$p['id']?>">Disable</button><?php endif;?></form></article><?php endforeach;?></section></main></body></html>
